import os.path
import yaml
from taf.config.cbts.environment_util import merge_map
from taf.config.testline.legacy.openstack import (HeatStacks, BTSHeatTemplate,
                                                  ExtNetHeatTemplate)
try:
    from urllib.request import urlopen
except ImportError:
    from urllib2 import urlopen


class HeatConfigCollector(object):
    def __init__(self, reader, bts_env_filename='config_bts.env',
                 net_env_filename='config_ext_net.env'):
        self.files_collector = reader
        self.control_collector = None
        self._bts_env_filename = bts_env_filename
        self._net_env_filename = net_env_filename

    def from_files(self, cfg_dirpath):
        """ Creates HeatStacks instance using env templates. To change default
        names assign other value when initializing class (`bts_env_filename`,
        `net_env_filename`)

        :cfg_dirpath: path to directory where config files are
        """
        bts = self._load_config(cfg_dirpath, self._bts_env_filename,
                                BTSHeatTemplate)
        net = self._load_config(cfg_dirpath, self._net_env_filename,
                                ExtNetHeatTemplate)
        return HeatStacks(bts=bts, net=net)

    def _load_config(self, cfg_dirpath, cfg_filename, cfg_cls):
        is_remote_file = cfg_filename.startswith("http://") or cfg_filename.startswith("https://")
        if is_remote_file:
            env_filename = cfg_filename
        else:
            env_filename = os.path.join(cfg_dirpath, cfg_filename)
        env_dict = self.files_collector.from_files(env_filename)
        return cfg_cls(env_dict)


class HeatFilesCollector(object):
    def __init__(self, templates_reader):
        self.reader = templates_reader

    def from_files(self, cfg_path):
        """ Collects data from single template file and returns SingleTemplate
        instance.

        :cfg_path: path to config file
        """
        single_template = self.reader.load(cfg_path)
        return single_template.data


def create_configuration_data(environment_filepaths,
                              deep_merge_enabled=False,
                              merge_strings_enabled=False):
    # type: (list, bool, bool) -> dict
    """ Creates heat stack configuration data as dictionary. It is possible
    to pass multiple environment files. By default, the keyword will not
    `deep merge` the configuration. """
    configuration_data = {}
    for env_file_path in environment_filepaths:
        is_remote_file = env_file_path.startswith("http://") or env_file_path.startswith("https://")
        if not is_remote_file:
            with open(env_file_path, "r") as f:
                new_config = yaml.load(f, Loader=yaml.FullLoader)
        else:
            response = urlopen(env_file_path)
            new_config = yaml.load(response.read(), Loader=yaml.FullLoader)
            response.close()

        configuration_data = merge_map(
            configuration_data,
            new_config,
            deep_merge_enabled=deep_merge_enabled,
            merge_strings_enabled=merge_strings_enabled)

    return configuration_data
